\label{defJfunctionalrelation}
	In a presheaf topos $[{\cal C}^{\textup{op}}, {\bf Set }]$, a relation $R\rightarrowtail P\times Q$ (that is, an assignment $c\to R(c)$ to each object $c$ of $\cal C$ of a subset $R(c)$ of $P(c)\times Q(c)$ which is \emph{functorial} in the sense that for any arrow $f:c\to c'$ in $\cal C$, $P(f)\times Q(f)$ sends $R(c')$ to $R(c)$), is said to be \emph{$J$-functional from $P$ to $Q$} if it satisfies the following properties:
	\begin{enumerate}[(i)]
		\item for any $c\in {\cal C}$ and any $(x, y)\in P(c)\times Q(c)$,\\ if $\{f:d\to c \mid\ (P(f)(x), Q(f)(y))\in R(d)\}\in J(c)$ then $(x,y)\in R(c)$;

		\item for any $c\in {\cal C}$ and any $(x, y), (x', y')\in R(c)$, if $x=x'$ then $\{f:d\to c \mid Q(f)(y)=Q(f)(y')\}\in J(c)$;

		\item for any $c\in {\cal C}$ and any $x\in P(c)$, $\{f:d\to c \mid \exists y\in Q(d) \,(P(f)(x), y)\in R(d) \}\in J(c)$.
	\end{enumerate}

\label{remfunctionalrelations}
	\begin{enumerate}[(a)]
		\item By the above discussion, the $J$-functional relations $R\rightarrowtail P\times Q$ from $P$ to $Q$ are precisely the $c_{J}$-closed relations $R$ on $[{\cal C}^{\textup{op}}, {\bf Set }]$ whose image under $a_{J}$ is the graph of an arrow $a_{J}(P)\to a_{J}(Q)$ in ${\bf Sh}({\cal C}, J)$, that is the subobjects corresponding to the functional relations from $a_{J}(P)$ to $a_{J}(Q)$ under the bijection of Proposition \ref{propclosedsubobjects}.

		\item Any relation $R\rightarrowtail P\times Q$ on $[{\cal C}^{\textup{op}}, {\bf Set }]$ satisfying conditions (ii) and (iii) of Definition \ref{defJfunctionalrelation} admits a \emph{$J$-closure} $\overline{R}^{J}$, consisting of all the pairs $(x, y)\in P(c)\times Q(c)$ such that $\{f:d\to c \mid\ (P(f)(x), Q(f)(y))\in R(d)\}\in J(c)$, which satisfies all the conditions of the definition. 

		\item The $J$-functional relation $R_{\xi}$ corresponding to an arrow $\xi:a_{J}(P)\to a_{J}(Q)$ can be concretely described as follows: for any $(x,y)\in P(c)\times Q(c)$, $(x, y)\in R_{\xi}$ if and only if $(\xi\circ \eta_{P})(c)(x)=(\eta_{Q}(c))(y)$, where $\eta_{P}:P\to a_{J}(P)$ and $\eta_{Q}:Q\to a_{J}(Q)$ are the unit arrows.			
	\end{enumerate}

\label{propfuncionalassignment}
	We have a natural bijection between the $J$-functional relations $R$ from $P$ to $Q$ and the functions $f$ assigning to each element $x\in P(c)$ a $\equiv_{J}$-equivalence class of elements of $Q(c)$ (that is, a subset $A$ of $Q(c)$ such that for any $y\in A$ and $y'\in Q(c)$, $y\equiv_{J} y'$ if and only if $y'\in A$) which is \emph{functorial} in the sense that for any arrow $g:d\to c$ in $\cal C$, if $y\in f(x)$ then $Q(g)(y)\in f(P(g)(x))$, \emph{$J$-closed} in the sense that if $Q(g)(y)\in f(P(g)(x))$ for all the arrows $g$ of a $J$-covering sieve then $y\in f(x)$ and \emph{$J$-locally pointed} in the sense that for any $x\in P(c)$, $\{g:d\to c \mid f(P(g)(x))\neq \emptyset \}\in J(c)$. This correspondence sends 
	\begin{itemize}
		\item a function $f$ satisfying the above properties to the relation $R_{f}\rightarrowtail P\times Q$ consisting of the pairs $(x, y)$ such that $y\in f(x)$;

		\item a $J$-functional relation $R$ from $P$ to $Q$ to the function $f_{R}$ given by:
		\[
		f_{R}(x)=\{y\in Q(c) \mid (x, y)\in R(c)\}
		\]
		for any $x\in P(c)$.
	\end{itemize}

