\label{corfact}
	Let $A:{\cal C}\to {\cal E}$ be a functor from an essentially small category $\cal C$ to a Grothendieck topos $\cal E$, and $J$ be a Grothendieck topology on $\cal C$. Then the following conditions are equivalent:
	\begin{enumerate}[(i)]
		\item The weak morphism $(L_{A} \dashv R_{A})$ factors through the canonical geometric inclusion $i:{\bf Sh}({\cal C}, J)\hookrightarrow [{\cal C}^{\textup{op}}, {\bf Set }]$; 

		\item The functor $R_{A}$ takes values in ${\bf Sh}({\cal C}, J)$;

		\item The functor $L_{A}$ factors (necessarily uniquely up to isomorphism) through the associated sheaf functor $a_{J}:[{\cal C}^{\textup{op}}, {\bf Set }]\to {\bf Sh}({\cal C}, J)$.
	\end{enumerate}

\label{defcanonicalfunctor}
	\begin{enumerate}[(a)]
		\item Given a small-generated site $({\cal C}, J)$, we say that a functor $A:{\cal C}\to {\cal E}$ is \emph{$J$-continuous} if the hom functor $R_{A}:{\cal E}\to [{\cal C}^{\textup{op}}, {\bf Set }]$ takes values into ${\bf Sh}({\cal C}, J)$ (equivalently, by Corollary \ref{corfact}, if the functor $L_{A}: [{\cal C}^{\textup{op}}, {\bf Set }]\to {\cal E}$ factors through $a_{J}:[{\cal C}^{\textup{op}}, {\bf Set }] \to {\bf Sh}({\cal C}, J)$). 

		\item Given small-generated sites $({\cal C}, J)$ and $({\cal D}, K)$, a functor $A:{\cal C}\to {\cal D}$ is said to be $(J, K)$-continuous if $l'\circ A$ is $J$-continuous, where $l'$ is the canonical functor ${\cal D}\to {\bf Sh}({\cal D}, K)$.
	\end{enumerate}

\label{propequivGroth}
