\label{thmhyperconnectedlocalicfactorization}
	Let $F:({\cal C}, J)\to ({\cal D}, K)$ be a morphism of small-generated sites. Then the hyperconnected-localic factorization of the geometric morphism ${\bf Sh}(F)\circ {\bf Sh}(i_{K}^{s}):{\bf Sh}({\cal D}_{K}^{s}, C_{K}^{s})\simeq {\bf Sh}({\cal D}, K) \to {\bf Sh}({\cal C}, J)$ induced by $F$ can be identified with the factorization ${\bf Sh}(F^{s})\circ {\bf Sh}(i_{F}^{s})$, where
	${\cal D}_{F}^{s}$ is the full subcategory of ${\cal D}_{K}^{s}$ on the objects of the form $(F(c), S)$ for an object $c$ of $\cal C$ and a $K$-closed sieve $S$ on $F(c)$, $C_{K}^{s}|_{{\cal D}_{F}^{s}}$ is the Grothendieck topology induced by $C_{K}^{s}$ on ${\cal D}_{F}^{s}$, $i_{F}^{s}:({\cal D}_{F}^{s}, C_{K}^{s}|_{{\cal D}_{F}^{s}})\to ({\cal D}_{K}^{s}, C_{K}^{s})$ is the morphism of sites given by the canonical inclusion functor ${\cal D}_{F}^{s}\hookrightarrow {\cal D}_{K}^{s}$, and $F_{s}$ is the morphism of sites $({\cal C}, J)\to ({\cal D}_{F}^{s}, C_{K}^{s}|_{{\cal D}_{F}^{s}})$ given by the functor $F$.

\label{corhyperclocalicintepretation}
	Let $I:{\cal C}_{\mathbb T}\to {\cal C}_{\mathbb S}$ be an interpretation of a geometric theory $\mathbb T$ into a geometric theory ${\mathbb S}$. Let ${\mathbb T}_{I}$ be the expansion of $\mathbb T$ whose signature is obtained by adding a predicate symbol $R_{\psi}$ of sorts $I(\vec{x})$ for any context $\vec{x}$ over the signature of $\mathbb T$ and any geometric formula $\psi$ in the context $I(\vec{x})$ over the signature of $\mathbb S$, and whose axioms are all the sequents whose image under the extension of $I$ sending each predicate symbol $R_{\psi}$ to the corresponding formula $\{I(\vec{x}). \psi\}$ is provable in $\mathbb S$, and let $I_{s}$ be the obvious interpretation of $\mathbb T$ into ${\mathbb T}_{I}$.
	Then the hyperconnected-localic factorization of the geometric morphism ${\bf Set }[{\mathbb S}]\to {\bf Set }[{\mathbb T}]$ induced by $I$ can be identified with the composite ${\bf Sh}(I')\circ {\bf Sh}(I_{s})$.

\label{corflatequivalence2}
		Let $({\cal C}, J)$ be a small-generated site, $\cal E$ a Grothendieck topos and $F:{\cal C}\to {\cal E}$ a $J$-continuous flat functor inducing a geometric morphism $f:{\cal E}\to {\bf Sh}({\cal C}, J)$. Then $f$ is an equivalence if and only if the following conditions are satisfied:
		\begin{enumerate}[(i)]
			\item $F$ is cover-reflecting;

			\item for every subobject $A\rightarrowtail F(c)$ in $\cal E$ there exists a ($J$-closed) sieve $R$ on $c$ such that $A$ is the union of the images of the arrows $F(f)$ for $f\in R$;

			\item the objects of the form $F(c)$ for $c\in {\cal C}$ form a separating set for the topos $\cal E$.
		\end{enumerate}

\label{corsyntacticMorita}
	Let $I:{\cal C}_{\mathbb T}\to {\cal C}_{\mathbb S}$ be an interpretation of a geometric theory $\mathbb T$ into a geometric theory ${\mathbb S}$. Then $I$ induces a Morita-equivalence between $\mathbb T$ and $\mathbb S$ if and only if the following conditions are satisfied:

	\begin{enumerate}[(i)]
		\item for every sequent $\sigma$ over the signature of $\mathbb T$, if the sequent $I(\sigma)$ is provable in $\mathbb S$ then $\sigma$ is provable in $\mathbb T$;

		\item the image of $I$ is closed under subobjects (that is, for any sorts $A_{1}, \ldots, A_{n}$ of the signature of $\mathbb T$, every geometric formula $\psi$ over the signature of $\mathbb S$ in the context $I((x_{1}^{A_{1}}, \ldots, x_{n}^{A_{n}}))$ is $\mathbb T$-provably equivalent (in its context) to a formula of the form $I(\phi)$ for a geometric formula $\phi$ over the signature of $\mathbb T$ in the context $(x_{1}^{A_{1}}, \ldots, x_{n}^{A_{n}})$); 	 

		\item for every sort $B$ of the signature of $\mathbb S$, the object $\{x^{B}. \top\}$ is $J_{\mathbb S}$-covered by objects in the image of $I$.  
	\end{enumerate}

\label{corinclusionequivalence2}
	Let $f:{\cal F}\to {\cal E}$ be a geometric morphism. Then

	\begin{enumerate}[(i)]
		\item $f$ is an inclusion if and only if $f^{\ast}$ is locally surjective and its image is closed under subobjects.

		\item $f$ is an equivalence if and only if $f^{\ast}$ is faithful, locally surjective and its image is closed under subobjects.		
	\end{enumerate}

\label{remsurjectioncomorphismofsites}
	\begin{enumerate}[(a)]
		\item If $F$ is $K$-full then the condition $J=K^{F}$ implies that $F$ is cover-preserving. Indeed, for any $R\in K(d')$, the sieve $\langle F(R)\rangle  $ is $J$-covering, since, by the $K$-fullness of $F$, for any arrow $x:F(d)\to F(d')$ in $\cal C$ there are a set $I$ and arrows $f_{i}:d_{i}\to d, g_{i}:d_{i}\to d'$ (for $i\in I$) such that the family $\{f_{i}:d_{i}\to d \mid i\in I\}$ is $K$-covering and $x\circ F(f_{i})=F(g_{i})$, and hence the sieve $T:=\{f_{i}\circ h \mid i\in I, h\in  g_{i}^{\ast}(R) \}$ is $K$-covering and satisfies the property $F(T)\subseteq x^{\ast}(S)$. 

		\item If $J$ and $K$ are the trivial topologies then $F$ is clearly cover-preserving and the condition that $F$ be $J$-dense is equivalent to the requirement that every object of $\cal D$ should be a retract of an object in the image of $F$. In fact, this was also proved with other means in Example A4.2.7(b) \cite{El}.	 
	\end{enumerate}

\label{lemprop}
	Let $c, c'\in {\cal C}$, $\xi:A_{F}(c)=a_{K}(\textup{Hom}_{\cal C}(F(-),c))\to A_{F}(c')=a_{K}(\textup{Hom}_{\cal C}(F(-),c'))$ an arrow in ${\bf Sh}({\cal D}, K)$ and $R_{\xi}$ the functional relation from $\textup{Hom}_{\cal C}(F(-),c)$ to $\textup{Hom}_{\cal C}(F(-),c')$ associated with it as in Remark \ref{remfunctionalrelations}(c). Then 
	\begin{enumerate}[(i)]
		\item For any arrows $f:c''\to c$ and $g:c''\to c'$, $\xi\circ A_{F}(f)=A_{F}(g)$ if and only if for every $x:F(e)\to c''$, $(f\circ x, g\circ x)\in R_{\xi}$. 

		\item There exist a family of arrows $f_{i}:c_{i}\to c$ in $\cal C$ which is sent by $A_{F}$ to an epimorphic family and a family of arrows $g_{i}:c_{i}\to c'$ in $\cal C$ such that $\xi\circ A_{F}(f_{i})=A_{F}(g_{i})$ for all $i$ if and only if there exists a family $(u_{j}, v_{j})$ of elements of $R_{\xi}$ such that the family $\{A_{F}(u_{j})\}$ is epimorphic and for any arrow $s:F(e)\to \textup{dom}(u_{j})=\textup{dom}(v_{j})$ in $\cal C$, $(u_{j}\circ s, v_{j}\circ s)\in R_{\xi}$.
	\end{enumerate}

\label{propsatisfactionconditionii}
	Let  $F:({\cal D}, K)\to ({\cal C}, J)$ be a comorphism of sites. Then the flat functor $A_{F}:{\cal C}\to {\bf Sh}({\cal D}, K)$ satisfies condition (ii) of Corollary \ref{corinclusionflatfunctor} if and only if for every $K$-functional relation $R$ from $\textup{Hom}_{\cal C}(F(-), c)$ to $\textup{Hom}_{\cal C}(F(-), c')$ in $[{\cal D}^{\textup{op}}, {\bf Set }]$ there exists a family $(f_{i}, g_{i})$ of arrows $f_{i}:\textup{dom}(f_{i}) \to c$ and $g_{i}:\textup{dom}(g_{i}) \to c'$ with common domain $\textup{dom}(f_{i})=\textup{dom}(g_{i})$ such that
	\begin{itemize}
		\item for any arrow $x:F(e)\to c$ there exists a $K$-covering sieve $T$ on $e$ such that, for every $t\in T$, $x\circ F(t)$ factors through some $f_{i}$;

		\item for any arrow $x:F(e)\to \textup{dom}(f_{i})=\textup{dom}(g_{i})$ in $\cal C$, $(f_{i}\circ x, g_{i}\circ x)\in R$.
	\end{itemize}
In particular, this condition is satisfied if $F$ is $K$-full.   

If $F$ is cover-preserving then the conjunction of the two conditions above is equivalent to the requirement that for any $(f,g)\in R$ and any arrow $x:F(e)\to \textup{dom}(f)=\textup{dom}(g)$ in $\cal C$, $(f\circ x, g\circ x)\in R$.

\label{lemmacomorphisminclusion}
Let $F:({\cal D}, K)\to ({\cal C}, J)$ be a comorphism of sites. Then for any object $d$ of $\cal D$ and any arrow $g:d'\to d$ in $\cal D$, the arrows $\xi:A_{F}(F(d'))\to l'(d)$ such that $\xi\circ \chi_{d'}=l'(g)$ can be identified with the relations $R$ from $\textup{Hom}_{\cal C}(F(-),F(d'))$ to $\textup{Hom}_{\cal D}(-,d)$ which assign to each object $e$ of $\cal C$ a collection $R(e)$ of pairs of arrows $(x:F(e)\to F(d'), y:e\to d)$ in such a way that the following properties are satisfied:
		\begin{enumerate}[(i)]
		\item for any $\xi:e'\to e$ in $\cal D$, if $(x, y)\in R$ then $(x\circ F(\xi), y\circ \xi)\in R$;	

		\item  for any $e\in {\cal D}$ and any $(x, y)\in \textup{Hom}_{\cal C}(F(e), F(d'))\times \textup{Hom}_{\cal C}(e,d)$, if $\{\xi:e'\to e \mid\ (x\circ F(\xi), y\circ \xi)\in R(e')\}\in K(e)$ then $(x,y)\in R(e)$;

		\item for any $e\in {\cal D}$, if $(x, y), (x', y')\in R$ and $x=x'$ then $y\equiv_{K} y'$;  

		\item for any $e\in {\cal D}$ and any arrow $x:F(e)\to F(d')$ in $\cal C$, $\{t:e'\to e \mid \exists y:e'\to d, \,(x\circ F(t), y)\in R(e') \}\in K(e)$;

		\item for any arrow $f:e\to d'$ in $\cal D$, $(F(f), g\circ f)\in R(e)$.	
\end{enumerate}
In particular, if $F$ is $K$-full and $K$-faithful then for every $d\in {\cal D}$ the arrow $\chi_{d'}:l'(d)\to A_{F}(F(d))$ is an isomorphism.

$$
\xymatrix{
	{\mathcal C} \ar[r]^F \ar[d]_{l'} &{\cal D} \ar[d]^{l} \\
	{\bf Sh}({\cal D}, K) \ar[r]^{(C_{F})_{!}} & {\bf Sh}({\cal C}, J)
}
$$

\label{lemmacomorphismlocalic}
	Let $F:({\cal D}, K)\to ({\cal C}, J)$ be a comorphism of sites. Then for any object $d$ of $\cal D$ and any arrow $g:d'\to d$ in $\cal D$, the arrows $\xi$ to $l'(d)$ whose domain is a subobject $s:S\rightarrowtail A_{F}(F(d'))$ through which $\chi_{d'}$ factors as $\chi_{d'}=s\circ \overline{\chi_{d'}}$, and such that $\xi\circ \overline{\chi_{d'}}=l'(g)$, can be identified with the relations $R$ from $\textup{Hom}_{\cal C}(F(-),F(d'))$ to $\textup{Hom}_{\cal D}(-,d)$ satisfying all the conditions of Lemma \ref{lemmacomorphisminclusion} but condition (iv). 	

The functor $F$ is $K$-faithful if and only if for every object $d$ of $\cal D$, the arrow $\chi_{d}:l'(d)\to A_{F}(F(d))$ is a monomorphism.

\label{proplocaliccomoprhismofsites}
	The geometric morphism $C_{F}:{\bf Sh}({\cal D}, K)\to {\bf Sh}({\cal C}, J)$ induced by a comorphism of sites $F:({\cal D}, K)\to ({\cal C}, J)$ is localic if and only if for every object $d$ of $\cal D$ there exist a $K$-covering sieve $\{g_{i}:d_{i}\to d \mid i\in I\}$ on $d$ and relations $R_{i}$ from $\textup{Hom}_{\cal C}(F(-),F(d_{i}))$ to $\textup{Hom}_{\cal D}(-,d)$  satisfying the conditions of Lemma \ref{lemmacomorphismlocalic}.

	In particular, if $F$ is $K$-faithful then the geometric morphism $C_{F}$ is localic.

\label{prophyperconnectedcomoprhismofsites}
	The geometric morphism $C_{F}:{\bf Sh}({\cal D}, K)\to {\bf Sh}({\cal C}, J)$ induced by a comorphism of sites $F:({\cal D}, K)\to ({\cal C}, J)$ is hyperconnected if and only if $F$ satisfies the property of Proposition \ref{propsurjectioncomorphismofsites} and for every object $c$ of $\cal C$ and any set $A$ of arrows of the form $x:F(d)\to c$ (for an object $d$ of $\cal D$) which is functorial (in the sense that if $x\in A$ then $x\circ F(g)\in A$ for any arrow $g:d'\to d$ in $\cal D$) and $K$-closed (in the sense that for any $K$-covering sieve $T$ on $d$, if $x\circ F(t)\in A$ for every $t\in T$ then $x\in A$) there exists a ($J$-closed) sieve $S$ on $c$ such that 	
	\begin{equation*}\begin{split}
	A &= \{x:F(d)\to c \mid d\in {\cal D}\textup{, } \{t:\textup{dom}(t)\to d \mid x\circ F(t)\in S\}\in K(d)\}. 
	\end{split}\end{equation*}
	If particular, if $F$ is $K$-full this latter condition is satisfied.

\begin{equation*}\begin{split}
	A &= \{x:F(d)\to c \mid d\in {\cal D}\textup{, } \{t:\textup{dom}(t)\to d \mid x\circ F(t)\in S\}\in K(d)\}. 
	\end{split}\end{equation*}

The geometric morphism $C_{F}:{\bf Sh}({\cal D}, K)\to {\bf Sh}({\cal C}, J)$ induced by a comorphism of sites $F:({\cal D}, K)\to ({\cal C}, J)$ is an equivalence if and only if the following conditions are satisfied:
\begin{enumerate}[(i)]
	\item for every object $d$ of $\cal D$ there exist a $K$-covering sieve $\{g_{i}:d_{i}\to d \mid i\in I\}$ on $d$ and  relations $R_{i}$ from $\textup{Hom}_{\cal C}(F(-),F(d_{i}))$ to $\textup{Hom}_{\cal D}(-,d)$ satisfying all the conditions of Lemma \ref{lemmacomorphisminclusion} but condition (iv); 

	\item $J=K^{F}$, that is, if a sieve $S$ on an object $c\in {\cal C}$ satisfies the property that for every object $d$ of $\cal D$ and arrow $x:F(d)\to c$ there exists a $K$-covering sieve $T$ on $d$ such that for every $g\in T$, $x\circ F(g)\in S$ then $S$ is $J$-covering;  

	\item for every object $c$ of $\cal C$ and any set $A$ of arrows of the form $x:F(d)\to c$ for an object $d$ of $\cal D$ which is functorial (in the sense that if $x\in A$ then $x\circ F(g)\in A$ for any arrow $g:d'\to d$ in $\cal D$) and $K$-closed (in the sense that for any $K$-covering sieve $T$ on $d$, if $x\circ F(t)\in A$ for every $t\in T$ then $x\in A$) there exists a ($J$-closed) sieve $S$ on $c$ such that 	
	\begin{equation*}\begin{split}
	A &= \{x:F(d)\to c \mid d\in {\cal D}\textup{, } \{t:\textup{dom}(t)\to d \mid x\circ F(t)\in S\}\in K(d)\}. 
	\end{split}\end{equation*}
\end{enumerate}	
	In particular, if $F$ is $K$-full and $K$-faithful and $J$-dense then $C_{F}$ is an equivalence.

\begin{equation*}\begin{split}
	A &= \{x:F(d)\to c \mid d\in {\cal D}\textup{, } \{t:\textup{dom}(t)\to d \mid x\circ F(t)\in S\}\in K(d)\}. 
	\end{split}\end{equation*}

\label{propmorphismcomorphismequivalence}
	Let $F:{\cal D}\to {\cal C}$ be a functor which is both a comorphism of sites and a morphism of sites $({\cal D}, K)\to ({\cal C}, J)$, where $J$ and $K$ are Grothendieck topologies respectively on $\cal C$ and $\cal D$. Then the following conditions are equivalent:

	\begin{enumerate}[(i)]
		\item The geometric morphism $C_{F}$ is an equivalence with quasi-inverse ${\bf Sh}(F)$.

		\item $F$ is $K$-full and $J$-dense (equivalently, a dense morphism of sites $({\cal D}, K)\to ({\cal C}, J)$).
	\end{enumerate}

